import {matchSession} from './match-session.js';
import {PITCHSIDE} from './pitchside-story.js';

const $=id=>document.getElementById(id),el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;};
let room=null,base='',timer,busy=false,stopped=true,failures=0;
const config=fetch('api-config.json').then(r=>r.json()).then(c=>base=c.baseUrl||'');
const dialog=el('dialog','pocket-pair-dialog'),close=el('button','pocket-pair-close','×'),stage=el('div','pocket-pair-stage'),copy=el('div','pocket-pair-copy'),qrWrap=el('div','pocket-qr'),qr=el('img'),code=el('b','pocket-code'),status=el('p','pocket-pair-status','Preparing a secure read-only session…'),actions=el('div','pocket-pair-actions'),open=el('a','pocket-primary','Open Pocket Director ↗'),copyLink=el('button','','Copy phone link'),stop=el('button','','Stop pairing');
dialog.setAttribute('aria-label','Pair Pocket Director');close.setAttribute('aria-label','Close pairing');close.onclick=()=>typeof dialog.close==='function'?dialog.close():dialog.removeAttribute('open');qr.alt='Scannable QR code for the BTR Pocket Director';open.target='_blank';open.rel='noopener';open.hidden=true;qrWrap.append(qr,code);actions.append(open,copyLink,stop);copy.append(el('span','pocket-pair-eyebrow','BTR / SECOND SCREEN'),el('h2','','PUT THE PROOF IN YOUR HAND.'),el('p','','Scan once. Your phone follows the same match clock, evidence revision and selected player—then lets you question the story without covering the action.'),status,actions,el('small','','READ-ONLY LINK · 30-MINUTE SESSION · SYNTHETIC MATCH DATA'));stage.append(copy,qrWrap);dialog.append(close,stage);document.body.append(dialog);
function input(){const s=matchSession.get();return {...s,clip_id:PITCHSIDE.id,time:s.source==='pitchside'?s.clipTime:s.time};}
async function call(path,body,key){const r=await fetch(base+path,{method:'POST',headers:{'Content-Type':'application/json',...(key?{Authorization:'Bearer '+key}:{})},body:JSON.stringify(body),signal:AbortSignal.timeout(8000)}),data=await r.json();if(!r.ok)throw Error(data.error||'Pairing is unavailable.');return data;}
async function update(){if(!room||busy||stopped)return;busy=true;try{await call(`/api/broadcast/${room.id}/update`,input(),room.writeKey);failures=0;status.textContent=`SYNCED LIVE · ${input().source==='pitchside'?'60-second film':'synthetic match'} · expires ${new Date(room.expires_at).toLocaleTimeString([], {hour:'numeric',minute:'2-digit'})}`;}catch(error){status.textContent=error.message;if(++failures>=3){stopped=true;clearInterval(timer);status.textContent+=' Reopen pairing to start a fresh session.';}}finally{busy=false;}}
function renderQR(url){const maker=globalThis.qrcode(0,'M');maker.addData(url);maker.make();qr.src=maker.createDataURL(7,8);code.textContent=room.id.slice(0,3).toUpperCase()+' · '+room.id.slice(-3).toUpperCase();}
async function start(){if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','');status.textContent='Preparing a secure read-only session…';open.hidden=true;try{await config;if(room&&!stopped)await call(`/api/broadcast/${room.id}/stop`,{},room.writeKey);room=await call('/api/broadcast',input());stopped=false;failures=0;const url=new URL('pocket-director.html',location.href);url.hash=new URLSearchParams({room:room.id,key:room.readKey}).toString();open.href=url.href;open.hidden=false;renderQR(url.href);clearInterval(timer);timer=setInterval(update,1000);await update();}catch(error){status.textContent=error.message+' You can still open the interactive companion demo.';const demo=new URL('pocket-director.html',location.href);open.href=demo.href;open.hidden=false;qr.removeAttribute('src');code.textContent='DEMO READY';}}
copyLink.onclick=async()=>{try{await navigator.clipboard.writeText(open.href);copyLink.textContent='Link copied';setTimeout(()=>copyLink.textContent='Copy phone link',1500);}catch{status.textContent='Open the phone experience, then copy its address from the browser.';}};
stop.onclick=async()=>{stopped=true;clearInterval(timer);try{if(room)await call(`/api/broadcast/${room.id}/stop`,{},room.writeKey);}catch{}status.textContent='Pairing stopped. The phone keeps its last reviewed moment.';};
window.addEventListener('pagehide',()=>{clearInterval(timer);if(room&&!stopped)fetch(base+`/api/broadcast/${room.id}/stop`,{method:'POST',headers:{Authorization:'Bearer '+room.writeKey},keepalive:true}).catch(()=>{});});
$('pocket-director').onclick=start;
const headerPair=el('button','pocket-header-pair','PAIR PHONE');
headerPair.type='button';
headerPair.onclick=start;
document.querySelector('.header-end')?.prepend(headerPair);
